    test("emits per-page .translations.json for each HTML entry", async () => {
      const bareRollupMock = require("rollup").rollup;
      const globMock = glob as jest.Mock;

      globMock.mockResolvedValueOnce([
        "src/client/page1.html",
        "src/client/page2.html",
      ]);

      // The perPageTranslations plugin runs inside generateBundle before
      // rollup produces its output. We simulate its effect by returning
      // output that already has per-page filenames — the plugin renamed
      // them in the bundle object before rollup serialized the result.
      bareRollupMock
        .mockResolvedValueOnce(
          makeBuildWithOutput([
            { type: "chunk", isEntry: true, fileName: "page1.js" },
            { type: "asset", fileName: "page1.html", source: "<html></html>" },
            {
              type: "asset",
              fileName: "page1.translations.json",
              source: JSON.stringify({ messages: ["Save", "Cancel"] }),
            },
          ]),
        )
        .mockResolvedValueOnce(
          makeBuildWithOutput([
            { type: "chunk", isEntry: true, fileName: "page2.js" },
            { type: "asset", fileName: "page2.html", source: "<html></html>" },
            {
              type: "asset",
              fileName: "page2.translations.json",
              source: JSON.stringify({ messages: ["Cancel", "Delete"] }),
            },
          ]),
        );

      const fs = makeFs();
      const build = await rollup({
        fs,
        input: "src/client/*.html",
      });
      const result = await build.generate({ dir: "dist" });

      // Each page should have its own translations file
      const page1Translations = result.output.find(
        (o) => o.type === "asset" && o.fileName === "page1.translations.json",
      );
      const page2Translations = result.output.find(
        (o) => o.type === "asset" && o.fileName === "page2.translations.json",
      );

      expect(page1Translations).toBeDefined();
      const parsed1 = JSON.parse((page1Translations as any).source);
      expect(parsed1.messages).toEqual(["Save", "Cancel"]);

      expect(page2Translations).toBeDefined();
      const parsed2 = JSON.parse((page2Translations as any).source);
      expect(parsed2.messages).toEqual(["Cancel", "Delete"]);

      // No generic .translations.json should exist
      const genericTranslations = result.output.find(
        (o) => o.type === "asset" && o.fileName === ".translations.json",
      );
      expect(genericTranslations).toBeUndefined();
    });

