    test("multiple vendor chunks from one entry get separate hashes", async () => {
      const bareRollupMock = require("rollup").rollup;
      const globMock = glob as jest.Mock;

      globMock.mockResolvedValueOnce(["src/client/page1.html"]);

      let extractPlugin: any;
      bareRollupMock.mockImplementation((opts: any) => {
        const plugin = (opts.plugins as any[]).find(
          (p: any) => p && p.name === "extract-large-modules",
        );
        if (plugin && !extractPlugin) {
          extractPlugin = plugin;
        }
        return Promise.resolve(
          makeBuildWithOutput([
            { type: "chunk", isEntry: true, fileName: "page.js" },
          ]),
        );
      });

      const build = await rollup({
        fs: makeFs(),
        input: "src/client/*.html",
      });
      await build.generate({ dir: "dist" });

      // Two large modules extracted from same entry
      const largeCode = "x".repeat(200_001);
      extractPlugin.transform(
        largeCode,
        "/project/node_modules/react-dom/index.js",
      );
      extractPlugin.transform(
        largeCode + " different",
        "/project/node_modules/lodash/index.js",
      );

      const outputOpts = extractPlugin.outputOptions({});
      expect(
        outputOpts.manualChunks(
          "/project/node_modules/react-dom/index.js",
          {} as any,
        ),
      ).toBe("vendor-react-dom--page1");
      expect(
        outputOpts.manualChunks(
          "/project/node_modules/lodash/index.js",
          {} as any,
        ),
      ).toBe("vendor-lodash--page1");

      // generateBundle renames both to content hashes
      const bundle: Record<string, any> = {
        "page.js": {
          type: "chunk",
          isEntry: true,
          fileName: "page.js",
          name: "page",
          code: "import './vendor-react-dom--page1.jsdbx';\nimport './vendor-lodash--page1.jsdbx';",
        },
        "vendor-react-dom--page1.jsdbx": {
          type: "chunk",
          isEntry: false,
          fileName: "vendor-react-dom--page1.jsdbx",
          name: "vendor-react-dom--page1",
          code: "var react = 'react code';",
        },
        "vendor-lodash--page1.jsdbx": {
          type: "chunk",
          isEntry: false,
          fileName: "vendor-lodash--page1.jsdbx",
          name: "vendor-lodash--page1",
          code: "var lodash = 'lodash code';",
        },
      };
      await extractPlugin.generateBundle({}, bundle);

      // Both entry-tagged keys should be gone
      expect(bundle["vendor-react-dom--page1.jsdbx"]).toBeUndefined();
      expect(bundle["vendor-lodash--page1.jsdbx"]).toBeUndefined();

      // Two distinct hash-named vendor chunks
      const reactKeys = Object.keys(bundle).filter((k) =>
        k.startsWith("vendor-react-dom--"),
      );
      const lodashKeys = Object.keys(bundle).filter((k) =>
        k.startsWith("vendor-lodash--"),
      );
      expect(reactKeys).toHaveLength(1);
      expect(lodashKeys).toHaveLength(1);
      expect(reactKeys[0]).toMatch(/^vendor-react-dom--[0-9a-f]{8}\.jsdbx$/);
      expect(lodashKeys[0]).toMatch(/^vendor-lodash--[0-9a-f]{8}\.jsdbx$/);

      // Entry chunk references both new filenames
      expect(bundle["page.js"].code).toContain(reactKeys[0]);
      expect(bundle["page.js"].code).toContain(lodashKeys[0]);
    });

